import itertools
def has_sym(S,h,w):
    res={}
    res['rot180']=all((h-1-r,w-1-c) in S for r,c in S)
    res['vert']=all((r,w-1-c) in S for r,c in S)
    res['horiz']=all((h-1-r,c) in S for r,c in S)
    res['transpose']=all((c,r) in S for r,c in S)
    res['anti']=all((w-1-c,h-1-r) in S for r,c in S)
    res['diag_anti']=all((w-1-c,r) in S for r,c in S)
    res['diag2']=all((c,h-1-r) in S for r,c in S)
    return res
